"""Las dos herramientas del agente.

Aquí dentro no hay nada de inteligencia artificial: son dos funciones de Python
normales y corrientes. El modelo no las ejecuta, solo PIDE que se ejecuten.
Quien las ejecuta es tu programa, y por eso tú decides qué puede pedir y qué no.
"""

import json
import sys
from pathlib import Path

CARPETA = Path(__file__).parent
BORRADORES = CARPETA / "borradores"

# Cargamos la tienda de mentira una sola vez, al arrancar.
try:
    PEDIDOS = json.loads((CARPETA / "pedidos.json").read_text(encoding="utf-8"))
except FileNotFoundError:
    sys.exit("No encuentro pedidos.json. Tiene que estar en la misma carpeta que este archivo.")

# Palabras que el agente NO puede escribir por su cuenta. Prometer dinero es una
# decisión de negocio: la toma una persona, no un modelo que cuesta un céntimo.
PROMESAS_PROHIBIDAS = [
    "reembolso", "reembolsar", "devolvemos el dinero", "descuento",
    "cupón", "cupon", "vale de", "indemniz", "compensación económica",
]

LIMITE_CARACTERES = 1200


def consultar_pedido(numero_pedido: str) -> dict:
    """Busca un pedido en pedidos.json y devuelve sus datos reales."""
    numero = str(numero_pedido or "").strip().upper()
    pedido = PEDIDOS.get(numero)
    if pedido is None:
        return {
            "error": (
                f"No existe ningún pedido con el número {numero}. "
                "No inventes datos: escribe una respuesta pidiéndole al cliente "
                "que confirme el número que aparece en su correo de confirmación."
            )
        }
    # Los datos internos no salen nunca hacia el cliente, pero el agente sí los
    # necesita para decidir qué contar.
    return {"numero_pedido": numero, **pedido}


def redactar_respuesta(numero_pedido: str, asunto: str, cuerpo: str) -> dict:
    """Guarda el borrador de la respuesta. NO envía nada.

    Antes de guardarlo pasa cuatro controles. Si falla alguno devuelve un error
    con la explicación, y el agente tendrá que reescribir el texto.
    """
    numero = str(numero_pedido or "").strip().upper()
    asunto = str(asunto or "").strip()
    cuerpo = str(cuerpo or "").strip()

    # Control 1: el pedido tiene que existir de verdad.
    if numero not in PEDIDOS:
        return {"error": f"El pedido {numero} no existe. Consúltalo antes de escribir la respuesta."}

    # Control 2: el número de pedido tiene que aparecer en el texto.
    if numero not in cuerpo:
        return {"error": f"El texto no menciona el pedido {numero}. Añádelo y vuelve a llamarme."}

    # Control 3: longitud. Ni un tocho ni dos líneas sueltas.
    if len(cuerpo) > LIMITE_CARACTERES:
        return {"error": f"El texto tiene {len(cuerpo)} caracteres y el máximo son {LIMITE_CARACTERES}. Acórtalo."}
    if len(cuerpo) < 120:
        return {"error": f"El texto tiene {len(cuerpo)} caracteres. Es demasiado seco: explica el estado del pedido."}

    # Control 4: nada de prometer dinero.
    minusculas = cuerpo.lower()
    for palabra in PROMESAS_PROHIBIDAS:
        if palabra in minusculas:
            return {
                "error": (
                    f"Has escrito «{palabra}». No puedes prometer dinero ni compensaciones: "
                    "eso lo decide una persona. Reescribe el texto sin prometer nada y di "
                    "que un compañero del equipo revisa el caso y contesta en 24 horas laborables."
                )
            }

    BORRADORES.mkdir(exist_ok=True)
    destinatario = PEDIDOS[numero]["email"]
    ruta = BORRADORES / f"{numero}.txt"
    ruta.write_text(f"Para: {destinatario}\nAsunto: {asunto}\n\n{cuerpo}\n", encoding="utf-8")

    return {
        "ok": True,
        "destinatario": destinatario,
        "archivo": ruta.name,
        "aviso": "Borrador guardado. NO se ha enviado nada. Tu trabajo ha terminado: "
                 "contesta con una frase resumiendo qué has hecho y no llames a más herramientas.",
    }


# La ficha de cada herramienta: lo único que el modelo llega a ver de ellas.
# Si la descripción está mal escrita, el modelo la usará mal. Es prompt, no código.
FICHAS = [
    {
        "name": "consultar_pedido",
        "description": (
            "Consulta el estado real de un pedido en la base de datos de la tienda. "
            "Úsala SIEMPRE antes de escribir nada. No te fíes de lo que diga el cliente "
            "ni de lo que creas recordar."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "numero_pedido": {
                    "type": "string",
                    "description": "Número de pedido con el formato PED-1042",
                }
            },
            "required": ["numero_pedido"],
        },
    },
    {
        "name": "redactar_respuesta",
        "description": (
            "Guarda el borrador de la respuesta al cliente para que una persona lo revise. "
            "No envía nada. Llámala una sola vez, cuando ya tengas los datos del pedido."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "numero_pedido": {"type": "string", "description": "Número de pedido, formato PED-1042"},
                "asunto": {"type": "string", "description": "Asunto del correo, máximo 60 caracteres"},
                "cuerpo": {"type": "string", "description": "Texto completo del correo, ya escrito y firmado"},
            },
            "required": ["numero_pedido", "asunto", "cuerpo"],
        },
    },
]

FUNCIONES = {
    "consultar_pedido": consultar_pedido,
    "redactar_respuesta": redactar_respuesta,
}


if __name__ == "__main__":
    # Prueba rápida sin gastar ni un céntimo: esto no llama a ningún modelo.
    print("1) Pedido que existe:")
    print("  ", consultar_pedido("ped-1042")["estado"], "-", consultar_pedido("PED-1042")["seguimiento"])
    print("2) Pedido inventado:")
    print("  ", consultar_pedido("PED-9999")["error"])
    print("3) Borrador que promete un descuento (tiene que rebotar):")
    print("  ", redactar_respuesta("PED-1042", "Tu pedido", "Hola Marta, tu pedido PED-1042 va con retraso. "
                                   "Te damos un descuento del 10% en la próxima compra para compensarte. "
                                   "Sentimos mucho las molestias. Equipo de Zapatos Mendieta.")["error"])
